describe('jws', () => {
    it('decode works', () => {
        const decoded = decodeJwsPayload(jws);
        expect(decoded).toBeDefined();
        expect(decoded.version).toEqual(1);
    });

    it('verify works', async () => {
        const decoded = await decodeVerifyJwsSignature(jws, 'message-system', false);
        expect(decoded).toBeDefined();
        expect(decoded.version).toEqual(1);
    });

    it('node-jwa analysis', () => {
        const signature = jws.split('.')[2];
        const securedInput = jws.split('.', 2).join('.');
        const publicKey = pubkeysSPKI.mainPublicKey.dev;

        const derSignature = formatEcdsa.joseToDer(signature, 'ES256').toString('base64');
        const verifier = crypto.createVerify('RSA-SHA256');
        verifier.update(securedInput);
        const result = verifier.verify(publicKey, derSignature, 'base64');
        expect(result).toBeTruthy();
    });
});
